def do_POST(self) -> None:  # noqa: N802
    if self.path == "/v1/machines":
        self._register()
        return
    capabilities_match = CAPABILITIES_PATH_PATTERN.fullmatch(self.path)
    if capabilities_match is not None:
        self._declare_capability(capabilities_match.group(1))
        return
    revocation_match = MACHINE_KEY_REVOCATION_PATH_PATTERN.fullmatch(
        urlsplit(self.path).path
    )
    if revocation_match is not None:
        self._revoke_key(
            revocation_match.group(1), revocation_match.group(2)
        )
        return
    keys_match = MACHINE_KEYS_PATH_PATTERN.fullmatch(urlsplit(self.path).path)
    if keys_match is not None:
        self._rotate_key(keys_match.group(1))
        return
    if self.path == "/v1/sla-templates":
        self._create_sla_template()
        return
    if self.path == "/v1/slas":
        self._create_sla()
        return
    confirmations_match = SLA_CONFIRMATIONS_PATH_PATTERN.fullmatch(self.path)
    if confirmations_match is not None:
        self._confirm_sla(confirmations_match.group(1))
        return
    telemetry_match = SLA_TELEMETRY_PATH_PATTERN.fullmatch(self.path)
    if telemetry_match is not None:
        self._post_telemetry(telemetry_match.group(1))
        return
    telemetry_batches_match = SLA_TELEMETRY_BATCHES_PATH_PATTERN.fullmatch(
        urlsplit(self.path).path
    )
    if telemetry_batches_match is not None:
        self._create_telemetry_batch(telemetry_batches_match.group(1))
        return
    telemetry_seals_match = SLA_TELEMETRY_SEALS_PATH_PATTERN.fullmatch(
        urlsplit(self.path).path
    )
    if telemetry_seals_match is not None:
        self._create_telemetry_seal(telemetry_seals_match.group(1))
        return
    evaluations_match = SLA_EVALUATIONS_PATH_PATTERN.fullmatch(self.path)
    if evaluations_match is not None:
        self._evaluate_sla(evaluations_match.group(1))
        return
    funds_match = FUNDS_PATH_PATTERN.fullmatch(self.path)
    if funds_match is not None:
        self._deposit_funds(funds_match.group(1))
        return
    if self.path == "/v1/settlements":
        self._create_settlement()
        return
    if self.path == "/v1/settlement-batches":
        self._create_settlement_batch()
        return
    if self.path == "/v1/disputes":
        self._create_dispute()
        return
    evidence_match = DISPUTE_EVIDENCE_PATH_PATTERN.fullmatch(
        urlsplit(self.path).path
    )
    if evidence_match is not None:
        self._submit_evidence(evidence_match.group(1))
        return
    snapshot_match = DISPUTE_EVIDENCE_SNAPSHOTS_PATH_PATTERN.fullmatch(
        urlsplit(self.path).path
    )
    if snapshot_match is not None:
        self._create_evidence_snapshot(snapshot_match.group(1))
        return
    proposals_match = DISPUTE_ADJUDICATION_PROPOSALS_PATH_PATTERN.fullmatch(
        urlsplit(self.path).path
    )
    if proposals_match is not None:
        self._create_adjudication_proposal(proposals_match.group(1))
        return
    escalations_match = DISPUTE_ESCALATIONS_PATH_PATTERN.fullmatch(
        urlsplit(self.path).path
    )
    if escalations_match is not None:
        self._create_escalation(escalations_match.group(1))
        return
    arbitrations_match = DISPUTE_ARBITRATIONS_PATH_PATTERN.fullmatch(
        urlsplit(self.path).path
    )
    if arbitrations_match is not None:
        self._create_arbitration(arbitrations_match.group(1))
        return
    resolution_match = DISPUTE_RESOLUTION_PATH_PATTERN.fullmatch(self.path)
    if resolution_match is not None:
        self._resolve_dispute(resolution_match.group(1))
        return
    if urlsplit(self.path).path == "/v1/evidence-proofs":
        self._create_evidence_proof()
        return
    if urlsplit(self.path).path == "/v1/delegations":
        self._create_delegation()
        return
    if urlsplit(self.path).path == "/v1/audit-checkpoints":
        self._create_audit_checkpoint()
        return
    if urlsplit(self.path).path == "/v1/audit-comparisons":
        self._create_audit_comparison()
        return
    if urlsplit(self.path).path == "/v1/audit-anchors":
        self._create_audit_anchor()
        return
    if urlsplit(self.path).path == "/v1/audit-verifications":
        self._create_audit_verification()
        return
    if urlsplit(self.path).path == "/v1/audit-proofs":
        self._create_audit_proof()
        return
    if urlsplit(self.path).path == "/v1/proof-checks":
        self._create_proof_check()
        return
    if urlsplit(self.path).path == "/v1/proof-check-witnesses":
        self._create_proof_check_witness()
        return
    if urlsplit(self.path).path == "/v1/proof-check-verifications":
        self._create_proof_check_verification()
        return
    if urlsplit(self.path).path == "/v1/proof-check-proofs":
        self._create_proof_check_proof()
        return
    if urlsplit(self.path).path == "/v1/proof-check-proof-witnesses":
        self._create_proof_check_proof_witness()
        return
    if urlsplit(self.path).path == "/v1/proof-check-proof-verifications":
        self._create_proof_check_proof_verification()
        return
    if urlsplit(self.path).path == "/v1/final-audit-proofs":
        self._create_final_audit_proof()
        return
    if urlsplit(self.path).path == "/v1/final-audit-proof-witnesses":
        self._create_final_audit_proof_witness()
        return
    if urlsplit(self.path).path == "/v1/final-audit-proof-verifications":
        self._create_final_audit_proof_verification()
        return
    if urlsplit(self.path).path == "/v1/final-audit-verification-proofs":
        self._create_final_audit_verification_proof()
        return
    if urlsplit(self.path).path == "/v1/final-audit-verification-proof-witnesses":
        self._create_final_audit_verification_proof_witness()
        return
    if urlsplit(self.path).path == "/v1/final-audit-verification-proof-verifications":
        self._create_final_audit_verification_proof_verification()
        return
    if urlsplit(self.path).path == "/v1/final-audit-verification-proof-verification-proofs":
        self._create_final_audit_verification_proof_verification_proof()
        return
    if (
        urlsplit(self.path).path
        == "/v1/final-audit-verification-proof-verification-proof-witnesses"
    ):
        self._create_final_audit_verification_proof_verification_proof_witness()
        return
    if (
        urlsplit(self.path).path
        == "/v1/final-audit-verification-proof-verification-proof-verifications"
    ):
        self._create_final_audit_verification_proof_verification_proof_verification()
        return
    delegation_revocation_match = DELEGATION_PATH_PATTERN.fullmatch(
        urlsplit(self.path).path
    )
    if delegation_revocation_match is not None:
        self._revoke_delegation(delegation_revocation_match.group(1))
        return
    self._json(HTTPStatus.NOT_FOUND, {"error": "not_found"})

def _register(self) -> None:
    idempotency_key = self.headers.get("Idempotency-Key")
    if idempotency_key is None or IDEMPOTENCY_KEY_PATTERN.fullmatch(idempotency_key) is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_idempotency_key"})
        return
    request_object = self._read_request_object()
    if request_object is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    public_key = request_object["publicKey"]
    machine_id = hashlib.sha256(bytes.fromhex(public_key)).hexdigest()
    status, payload = self._register_machine(idempotency_key, public_key, machine_id)
    self._json(status, payload)

def _read_raw_body(self) -> bytes | None:
    length_header = self.headers.get("Content-Length")
    if length_header is None:
        return None
    try:
        length = int(length_header)
    except ValueError:
        return None
    if length <= 0:
        return None
    return self.rfile.read(length)

def _read_json_object(
    self, body: bytes | None = None, *, unbounded_ints: bool = False
) -> dict[str, Any] | None:
    if body is None:
        body = self._read_raw_body()
        if body is None:
            return None
    try:
        text = body.decode("utf-8")
    except UnicodeDecodeError:
        return None
    try:
        # 任意长度整数仅限审计序号入口；其他入口保留全局转换保护。
        parsed = json.loads(
            text,
            object_pairs_hook=_unique_object,
            parse_int=_audit_json_int if unbounded_ints else int,

def _create_settlement_batch(self) -> None:
    # 批次写入口要求恰好一个合法 Idempotency-Key：缺失、重复或格式非法
    # 均为 400/invalid_request，且不查询任何资源。
    values = self.headers.get_all("Idempotency-Key")
    if values is None or len(values) != 1:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    idempotency_key = values[0]
    if IDEMPOTENCY_KEY_PATTERN.fullmatch(idempotency_key) is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    fields = self._read_settlement_batch_object()
    if fields is None:
        self._json(HTTPStatus.BAD_REQUEST, {"error": "invalid_request"})
        return
    status, payload = self._apply_settlement_batch(idempotency_key, fields)
    self._json(status, payload)

def _read_settlement_batch_object(self) -> dict[str, Any] | None:
    parsed = self._read_json_object()
    if parsed is None or set(parsed) != SETTLEMENT_BATCH_FIELDS:
        return None
    batch_id = parsed["id"]
    if not isinstance(batch_id, str) or TEMPLATE_ID_PATTERN.fullmatch(batch_id) is None:
        return None
    items = parsed["items"]
    if not isinstance(items, list):
        return None
    if not 1 <= len(items) <= SETTLEMENT_BATCH_MAX_ITEMS:
        return None
    seen: set[tuple[str, int]] = set()
    normalized_items: list[dict[str, Any]] = []
    for item in items:
        if not isinstance(item, dict) or set(item) != SETTLEMENT_BATCH_ITEM_FIELDS:
            return None
        sla_id = item["slaId"]
        if not isinstance(sla_id, str) or TEMPLATE_ID_PATTERN.fullmatch(sla_id) is None:
            return None
        evaluation_seq = item["evaluationSeq"]
        if not isinstance(evaluation_seq, int) or isinstance(evaluation_seq, bool):
            return None
        if evaluation_seq < 1:
            return None
        reference = (sla_id, evaluation_seq)
        if reference in seen:
            return None
        seen.add(reference)
        normalized_items.append(
            {"slaId": sla_id, "evaluationSeq": evaluation_seq}
        )
    return {"id": batch_id, "items": normalized_items}

def _apply_settlement_batch(
    self, idempotency_key: str, fields: dict[str, Any]
) -> tuple[HTTPStatus, dict[str, Any]]:
    request_json = json.dumps(fields, sort_keys=True, separators=(",", ":"))
    batch_id = fields["id"]
    items = fields["items"]
    with closing(connect(self.server.database_path)) as database:
        database.execute("BEGIN IMMEDIATE")
        try:
            record = database.execute(
                "SELECT batch_id, request_json, status, response_json"
                " FROM settlement_batch_idempotency_records WHERE key = ?",
                (idempotency_key,),
            ).fetchone()
            if record is not None:
                database.execute("ROLLBACK")
                if (
                    record["batch_id"] == batch_id
                    and record["request_json"] == request_json
                ):
                    return HTTPStatus(record["status"]), json.loads(
                        record["response_json"]
                    )
                return HTTPStatus.CONFLICT, {"error": "conflict"}
            existing_batch = database.execute(
                "SELECT 1 FROM settlement_batches WHERE id = ?",
                (batch_id,),
            ).fetchone()
            if existing_batch is not None:
                database.execute("ROLLBACK")
                return HTTPStatus.CONFLICT, {"error": "batch_exists"}
            # 按数组顺序沿用单笔结算规则逐项判定；前项余额可供后项使用，
            # 故余额读取后以 working_balances 贯穿整批，仅在提交时落库。
            working_balances: dict[str, int] = {}

            def account_balance(account_id: str) -> int:
                if account_id not in working_balances:
                    row = database.execute(
                        "SELECT balance_micros FROM ledger_accounts"
                        " WHERE account_id = ?",
                        (account_id,),
                    ).fetchone()
                    working_balances[account_id] = (
                        row["balance_micros"] if row is not None else 0
                    )
                return working_balances[account_id]

            planned: list[dict[str, Any]] = []
            for item in items:
                sla_id = item["slaId"]
                evaluation_seq = item["evaluationSeq"]
                sla = database.execute(
                    "SELECT machine_id, consumer_id, price_micros, state"
                    " FROM slas WHERE id = ?",
                    (sla_id,),
                ).fetchone()
                if sla is None:
                    database.execute("ROLLBACK")
                    return HTTPStatus.NOT_FOUND, {"error": "not_found"}
                if sla["state"] not in ("active", "sealed"):
                    database.execute("ROLLBACK")
                    return HTTPStatus.CONFLICT, {"error": "conflict"}
                evaluation = None
                if evaluation_seq <= INT64_MAX:
                    evaluation = database.execute(
                        "SELECT sla_id, response_json"
                        " FROM sla_evaluation_idempotency_records"
                        " WHERE evaluation_seq = ?",
                        (evaluation_seq,),
                    ).fetchone()
                if evaluation is None:
                    database.execute("ROLLBACK")
                    return HTTPStatus.NOT_FOUND, {"error": "not_found"}
                # 评估归属错误为 conflict。
                if evaluation["sla_id"] != sla_id:
                    database.execute("ROLLBACK")
                    return HTTPStatus.CONFLICT, {"error": "conflict"}
                existing = database.execute(
                    "SELECT 1 FROM settlements WHERE evaluation_seq = ?",
                    (evaluation_seq,),
                ).fetchone()
                if existing is not None:
                    database.execute("ROLLBACK")
                    return HTTPStatus.CONFLICT, {"error": "settlement_exists"}
                snapshot = json.loads(evaluation["response_json"])
                outcome = snapshot["outcome"]
                if outcome == "fulfilled":
                    result = "charged"
                    amount = sla["price_micros"] * snapshot["count"]
                    payer_id = sla["consumer_id"]
                    payee_id = sla["machine_id"]
                elif outcome == "breached":
                    result = "compensated"
                    amount = sla["price_micros"] * snapshot["violations"]
                    payer_id = sla["machine_id"]
                    payee_id = sla["consumer_id"]
                else:
                    result = "pending"
                    amount = 0
                    payer_id = None
                    payee_id = None
                if amount > AMOUNT_CAP_MICROS:
                    database.execute("ROLLBACK")
                    return HTTPStatus.CONFLICT, {"error": "amount_overflow"}
                if payer_id is not None:
                    payer_balance = account_balance(payer_id)
                    payee_balance = account_balance(payee_id)
                    if payee_balance + amount > AMOUNT_CAP_MICROS:
                        database.execute("ROLLBACK")
                        return HTTPStatus.CONFLICT, {"error": "amount_overflow"}
                    # 可用余额为总余额扣除全部 open 争议冻结后与零的较大值；
                    # 批次内前项过账只改变 working_balances，冻结额不随批次变化。
                    frozen_record = database.execute(
                        "SELECT COALESCE(SUM(amount_micros), 0) AS frozen"
                        " FROM disputes WHERE payee_id = ? AND state = 'open'",
                        (payer_id,),
                    ).fetchone()
                    payer_available = max(
                        0, payer_balance - frozen_record["frozen"]
                    )
                    if payer_available < amount:
                        database.execute("ROLLBACK")
                        return HTTPStatus.CONFLICT, {"error": "insufficient_funds"}
                    # 前项余额可供后项使用：立即在工作余额上顺序过账本项。
                    # 付款方与收款方可能为同一账户，须按分录顺序连续更新。
                    working_balances[payer_id] = payer_balance - amount
                    working_balances[payee_id] = (
                        working_balances[payee_id] + amount
                    )
                planned.append(
                    {
                        "sla_id": sla_id,
                        "evaluation_seq": evaluation_seq,
                        "result": result,
                        "amount": amount,
                        "payer_id": payer_id,
                        "payee_id": payee_id,
                    }
                )
            # 全部项通过后才取序号与时间：任一失败均不消耗序号。
            next_record = database.execute(
                "SELECT COALESCE(MAX(settlement_seq), 0) + 1 AS next_seq"
                " FROM settlements"
            ).fetchone()
            next_seq = next_record["next_seq"]
            created_at_ms = int(datetime.now(UTC).timestamp() * 1000)
            settlement_payloads: list[dict[str, Any]] = []
            for position, plan in enumerate(planned):
                settlement_seq = next_seq + position
                payer_id = plan["payer_id"]
                payee_id = plan["payee_id"]
                amount = plan["amount"]
                if payer_id is not None:
                    payer_after = self._adjust_account(
                        database, payer_id, -amount
                    )
                    payee_after = self._adjust_account(
                        database, payee_id, amount
                    )
                    self._record_entry(
                        database, "settlement", settlement_seq, payer_id,
                        -amount, payer_after, created_at_ms,
                    )
                    self._record_entry(
                        database, "settlement", settlement_seq, payee_id,
                        amount, payee_after, created_at_ms,
                    )
                database.execute(
                    "INSERT INTO settlements"
                    "(settlement_seq, sla_id, evaluation_seq, result,"
                    " amount_micros, payer_id, payee_id, created_at_ms)"
                    " VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
                    (
                        settlement_seq,
                        plan["sla_id"],
                        plan["evaluation_seq"],
                        plan["result"],
                        amount,
                        payer_id,
                        payee_id,
                        created_at_ms,
                    ),
                )
                database.execute(
                    "INSERT INTO settlement_batch_items"
                    "(batch_id, position, settlement_seq, sla_id, evaluation_seq)"
                    " VALUES (?, ?, ?, ?, ?)",
                    (
                        batch_id,
                        position,
                        settlement_seq,
                        plan["sla_id"],
                        plan["evaluation_seq"],
                    ),
                )
                settlement_payloads.append(
                    {
                        "settlementSeq": settlement_seq,
                        "evaluationSeq": plan["evaluation_seq"],
                        "result": plan["result"],
                        "amount": amount,
                        "createdAt": created_at_ms,
                    }
                )
            payload = {
                "id": batch_id,
                "createdAt": created_at_ms,
                "settlements": settlement_payloads,
            }
            database.execute(
                "INSERT INTO settlement_batches"
                "(id, created_at_ms, response_json) VALUES (?, ?, ?)",
                (
                    batch_id,
                    created_at_ms,
                    json.dumps(payload, separators=(",", ":")),
                ),
            )
            database.execute(
                "INSERT INTO settlement_batch_idempotency_records"
                "(key, batch_id, request_json, status, response_json)"
                " VALUES (?, ?, ?, ?, ?)",
                (
                    idempotency_key,
                    batch_id,
                    request_json,
                    int(HTTPStatus.CREATED),
                    json.dumps(payload, separators=(",", ":")),
                ),
            )
            database.execute("COMMIT")
            return HTTPStatus.CREATED, payload
        except BaseException:
            database.execute("ROLLBACK")
            raise

def _parse_settlement_batches_query(
    self, query: str
) -> tuple[str | None, int, tuple[int, int] | None] | None:
    # 仅接受 slaId/limit/cursor 且各至多一次；缺值、未知或重复参数、
    # 非法格式、越界 limit 与 lastSeq 大于 cut 均在此拒绝（400），
    # 不触碰任何资源状态。
    parameters: dict[str, list[str]] = {}
    for key, value in parse_qsl(query, keep_blank_values=True):
        parameters.setdefault(key, []).append(value)
    if not set(parameters) <= SETTLEMENT_BATCHES_QUERY_PARAMS:
        return None
    if any(len(values) != 1 for values in parameters.values()):

def do_GET(self) -> None:  # noqa: N802
    target = urlsplit(self.path)
    if target.path == "/health":
        with closing(connect(self.server.database_path)) as database:
            version = database.execute(
                "SELECT value FROM schema_metadata WHERE key = 'schema_version'"
            ).fetchone()[0]
        self._json(
            HTTPStatus.OK,
            {
                "status": "ok",
                "service": "service-sla-settlement-network",
                "schemaVersion": version,
                "time": datetime.now(UTC).isoformat(),
            },
        )
        return
    telemetry_match = SLA_TELEMETRY_PATH_PATTERN.fullmatch(target.path)
    if telemetry_match is not None:
        self._get_telemetry(telemetry_match.group(1), target.query)
        return
    telemetry_seal_match = SLA_TELEMETRY_SEAL_PATH_PATTERN.fullmatch(target.path)
    if telemetry_seal_match is not None:
        self._get_telemetry_seal(telemetry_seal_match.group(1), target.query)
        return
    telemetry_batch_match = TELEMETRY_BATCH_ITEM_PATH_PATTERN.fullmatch(
        target.path
    )
    if telemetry_batch_match is not None:
        self._get_telemetry_batch(telemetry_batch_match.group(1), target.query)
        return
    machine_delegations_match = MACHINE_DELEGATIONS_PATH_PATTERN.fullmatch(
        target.path
    )
    if machine_delegations_match is not None:
        self._get_machine_delegations(
            machine_delegations_match.group(1), target.query
        )
        return
    delegation_consumptions_match = (
        MACHINE_DELEGATION_CONSUMPTIONS_PATH_PATTERN.fullmatch(target.path)
    )
    if delegation_consumptions_match is not None:
        self._get_delegation_consumptions(
            delegation_consumptions_match.group(1), target.query
        )
        return
    delegation_events_match = DELEGATION_EVENTS_PATH_PATTERN.fullmatch(target.path)
    if delegation_events_match is not None:
        self._get_delegation_events(
            delegation_events_match.group(1), target.query
        )
        return
    evaluations_match = SLA_EVALUATIONS_PATH_PATTERN.fullmatch(target.path)
    if evaluations_match is not None:
        self._get_evaluations(evaluations_match.group(1), target.query)
        return
    settlements_match = SLA_SETTLEMENTS_PATH_PATTERN.fullmatch(target.path)
    if settlements_match is not None:
        self._get_settlements(settlements_match.group(1), target.query)
        return
    ledger_match = ACCOUNT_LEDGER_PATH_PATTERN.fullmatch(target.path)
    if ledger_match is not None:
        self._get_ledger(ledger_match.group(1), target.query)
        return
    if target.path == "/v1/settlement-batches":
        self._get_settlement_batches(target.query)
        return
    settlement_batch_match = SETTLEMENT_BATCH_ITEM_PATH_PATTERN.fullmatch(
        target.path
    )
    if settlement_batch_match is not None:
        self._get_settlement_batch(
            settlement_batch_match.group(1), target.query
        )
        return
    if target.path == "/v1/disputes":
        self._get_disputes(target.query)
        return
    dispute_events_match = DISPUTE_EVENTS_PATH_PATTERN.fullmatch(target.path)
    if dispute_events_match is not None:
        self._get_dispute_events(
            dispute_events_match.group(1), target.query
        )
        return
    dispute_evidence_match = DISPUTE_EVIDENCE_PATH_PATTERN.fullmatch(target.path)
    if dispute_evidence_match is not None:
        self._get_dispute_evidence(
            dispute_evidence_match.group(1), target.query
        )
        return
    evidence_proofs_match = EVIDENCE_PROOFS_PATH_PATTERN.fullmatch(target.path)
    if evidence_proofs_match is not None:
        self._get_evidence_proofs(
            evidence_proofs_match.group(1), target.query
